sections=[]
def sec(key,start,end,title,takeaway,paras,examples=(),notes=(),slides=()):
 sections.append(dict(key=key,start=start,end=end,title=title,takeaway=takeaway,paragraphs=list(paras),examples=list(examples),editor_notes=list(notes),slides=list(slides)))
sec('lab-background',0,104,'课程进入下半程：从个人助手到更深入的研究','一个日常 Agent 的价值，取决于上下文、任务设计和持续反馈，而不只是模型名称。',[
 '第 08 课把主题推进到 Agent-native 开发：当模型已经能调用工具、改动文件、执行任务，开发者应怎样组织它的工作？教师以自己积累长任务、利用额度重置前的时间运行数学证明等任务开场。这是个人使用情境，不是某个工具能保证证明成功的证据。',
 '第二个实验 Deeper Research 已发布。第一个实验偏向做一个自己的产品：围绕个人资料库，让 Agent 处理邮件、回答问题或提供信息服务。教师展示日常自动任务，包括给孩子生成在车上听的播客、推送 Morning Paper 和 GitHub Trending；论文摘要的提示词经过调整，直接要求模型“总结论文”不一定得到同样的阅读体验。',
 '第二个实验从这个个人 Agent 中抽出一小块，追问同一个问题：增加一些探索、查证和修改的预算，能否得到更好的结果？课程强调亲手观察 Agent 的实际轨迹，产品截图和效果描述只是起点。'],notes=['转写校订边界：开场的产品、模型与额度名称存在识别歧义；这里保留可核实的任务用途，不把可疑品牌或版本号当作准确事实。'])
sec('search',104,242,'算力换智力：既要向下做，也要向旁边找','预算应同时留给方案比较和落实验证；沿第一条路线做得更深，不等于找到了更好的路线。',[
 'Agent 已能完成较长任务，但“最初应该选择哪条路线”的直觉未必可靠。教师用研究生做研究作类比：想到一个合理想法后，可以不断实现原型、优化方法、改善实验，这是深度优先；它能把一个很窄的问题做深，却容易让人忘记更大的设计空间。',
 '设计空间在浅层就有许多分叉。不同方案可能把最终结果带到很远的地方，因此需要宽度优先的探索：在投入大量实现成本之前，把若干候选路线摆到一起比较。板书先画一个问题向下延伸的单一路径，再补上浅层分叉，说明搜索不是只有“继续改进当前答案”一种动作。',
 '算力有限，不能无限枚举，也不能永远调研而不落地。Lab2 要自己构建 Agent loop，让求解、审查、修改形成可控制的循环；真正需要设计的是什么时候继续深入、什么时候尝试另一条路，以及怎样保留较好的候选。'],examples=['课堂研究例：某种 Python 代码补全问题可以做得很窄、很深。训练研究者的目的还包括理解自己处在什么设计空间，能否找到更合适的解法；这个教学类比不等于模型训练过程的完整技术说明。'],notes=['现行 Lab2 补充：可以在同一基础模型、固定输入和预先定义的质量指标下，比较直接回答、低 effort 与高 effort。记录质量、延迟和 token 成本，尽量盲评并重复运行；“花得更多”不是质量提升的充分条件。'])
sec('humanize',242,358,'多样性与知识库：把复核变成真实的改进','不同模型和外部知识能拓宽探索，但必须用证据判断它们是否改进了答案。',[
 '教师以 Humanize 为参考，转述自己观察到的做法：让 GPT 与 Claude 相互 review、相互挑刺。两个带有不同偏好的模型可能提出不同路线，减轻一个模型沿同一方向一路走到底的问题。课堂用“两个互补的人”解释多样性；这是机制直觉和实践经验，不是所有多模型系统都优于单模型的定理。',
 '只增加来回轮数还不够，Agent 也需要可以检索的知识。第一个实验中的个人资料库可能有作业、奖学金申请、简历；做 Deeper Research 时，还需要研究论文、博客、GitHub 项目或书中相关片段，把外部知识带入问题求解。',
 '实验留有开放空间，实现可以简单。教师更看重学生真正观察过一次 Agent trajectory：它在何处搜索、依赖什么证据、为什么修改、怎样结束。只有亲手做过，才容易发现产品宣传和一次真实任务之间的差异。'],notes=['论文与课堂分层：下面的 Humanize v2 阅读补充来自 2026-10-08 的论文原文。课堂展示没有确认论文版本，补充不当作教师在这几分钟中逐项讲过的结论。'])
sec('intent',358,528,'Intent → Spec → Implementation：软件工程约束的是搜索空间','从意图到规格再到实现，每一步都有多种选择；沟通和工具帮助尽早排除不合适的分支。',[
 '教师把前半学期串成三层：intent 是想达到什么，specification 是把要求写成怎样的约束，implementation 是具体怎样实现。从意图到规格、从规格到实现都是一对多。人的注意力有限，一开始通常只在巨大的空间里选中一个点，不能把第一个想法当成唯一答案。',
 '不同层有不同的对齐对象。需求阶段用访谈、checklist 和甲方沟通，让“到底想做什么”更清楚；规格与架构阶段可以向有经验的人讨论数据库选择、事件溯源是否合适、状态如何持久化。反复讨论会产生不同方案，最终的可维护性和可观测性可能相差很大。',
 'UML 等建模方法的价值，在于给讨论施加可共同理解的约束，尽早暴露分歧。IDE、Git、worktree 和其他版本工具则帮助管理实现与状态。教师建议持续看真实项目使用了什么技术，并对不懂的地方追问；少量但连续的观察能积累判断力。'],examples=['事件溯源不是默认必选答案。教师提到某开发者不采用 event sourcing、但仍强调持久化状态的设计作为讨论例子；这里保留“需要比较设计取舍”的意思，不据这段口述断言该项目的全部架构。'],slides=[1])
sec('prototype',528,670,'让原型替你暴露未曾想过的问题','原型是验证当前假设的工具；先做一版、用典型场景评审，再决定如何改。',[
 'AI 降低了“从当前阶段直接往下做出一个版本”的成本。即使意图或规格尚不完善，也可以让它实现一个原型，再比较变好还是变坏。原型做不下去、变得难维护，或者用例暴露冲突，都可以成为下一轮讨论的反馈。',
 '很多设计问题只有实现之后才看得见：用户更多会怎样？某类人加入后会怎样？两个模块之间是否有此前没想到的交互？教师提出先做出版本，再构建典型 use case 进行评审，让实现帮助预测后果。这里的“先做”不是免除判断，而是把昂贵的猜测变成较便宜的试验。',
 '如果子系统需求能够分开，Agent 可以并行承担不同工作。教师展示自己的习惯是把终端分成四块，同时监督四个 Agent；超过这个数量，人的注意力会跟不上。这是个人经验，说明并行收益还受人类检查与协调能力约束。'],slides=[2])
sec('agent-loop',670,914,'Agent Loop 的最低组成：模型、工具和反馈','自主调用工具只是循环的起点，路线选择、停止和验证仍需要设计。',[
 '教师回顾从 ChatGPT 到早期 coding agent 的观感变化：模型可以产生自主行动，但早期幻觉让人难以直接信任它。一个不知疲倦的执行者看似能够不停尝试，现实中的模型却常在选定一条看起来可行的路线后持续推进，或在困难任务面前直接停止。',
 '课堂用强化学习中的完成任务压力解释这种倾向，并再次回到宽度和深度之间的平衡。把这段话理解为教师对行为的解释，不应扩写为某一闭源模型训练奖励的已核实细节。模型会思考、会调用工具，也不意味着它会自动投入最合适的探索预算。',
 '最低限度的 Agent 可以只获得一个 bash 或 Python 工具。Shell 能读写文件、运行程序和调用系统工具，因此很简单的工具接口也能连接很多能力。教师用“如果把自己的能力蒸馏给模型，只给一个 bash 也能做许多事”帮助理解工具通用性；“造芯片、证明黎曼猜想”是设想式例子，不能作为演示能力声明。'],slides=[3])
if __name__=='__main__':
 pathlib.Path('/tmp/gse08-sections-draft.json').write_text(json.dumps(sections,ensure_ascii=False,indent=2))
